class Solution {public:
 double minTime(int n,int k,int m,vector<int>& time,vector<double>& mul){
  int all=(1<<n)-1;const double INF=1e100;
  vector<vector<array<double,2>>> dist(1<<n,vector<array<double,2>>(m,{INF,INF}));
  using State=tuple<double,int,int,int>;priority_queue<State,vector<State>,greater<State>> pq;
  dist[0][0][0]=0;pq.emplace(0.0,0,0,0);
  while(!pq.empty()){
   double d;int mask,phase,side;tie(d,mask,phase,side)=pq.top();pq.pop();
   if(d>dist[mask][phase][side]+1e-9)continue;if(mask==all&&side==1)return d;
   int available=side?mask:(all^mask);
   for(int sub=available;sub;sub=(sub-1)&available){if(__builtin_popcount((unsigned)sub)>k)continue;
    if(side&&__builtin_popcount((unsigned)sub)!=1)continue;
    int t=0;for(int i=0;i<n;++i)if(sub>>i&1)t=max(t,time[i]);
    double cost=t*mul[phase];int next=(phase+(int)floor(cost))%m;
    int nm=side?(mask^sub):(mask|sub),ns=1-side;
    if(d+cost<dist[nm][next][ns]){dist[nm][next][ns]=d+cost;pq.emplace(d+cost,nm,next,ns);}
   }
  }return -1;
 }
};
